with open('/app/jwt.go', 'r') as f:
    content = f.read()

# Fix the verifyToken function to reject "none" algorithm and enforce proper signature verification
old_verify = '''func verifyToken(token string) (*Claims, error) {
	parts := strings.Split(token, ".")
	if len(parts) != 3 {
		return nil, errors.New("malformed token")
	}
	// Trust the token's own declared algorithm (the vulnerability).
	hraw, err := base64.RawURLEncoding.DecodeString(parts[0])
	if err != nil {
		return nil, err
	}
	var hdr struct {
		Alg string `json:"alg"`
	}
	if err := json.Unmarshal(hraw, &hdr); err != nil {
		return nil, err
	}
	// VULNERABLE: alg:"none" tokens are accepted without verifying any signature.
	if hdr.Alg != "none" {
		signingInput := parts[0] + "." + parts[1]
		if !hmac.Equal([]byte(sign(signingInput)), []byte(parts[2])) {
			return nil, errors.New("bad signature")
		}
	}'''

new_verify = '''func verifyToken(token string) (*Claims, error) {
	parts := strings.Split(token, ".")
	if len(parts) != 3 {
		return nil, errors.New("malformed token")
	}
	// Decode and validate the header
	hraw, err := base64.RawURLEncoding.DecodeString(parts[0])
	if err != nil {
		return nil, err
	}
	var hdr struct {
		Alg string `json:"alg"`
	}
	if err := json.Unmarshal(hraw, &hdr); err != nil {
		return nil, err
	}

	// SECURITY FIX: reject alg:"none" tokens to prevent forgery
	if hdr.Alg == "none" {
		return nil, errors.New("unsecured tokens not allowed")
	}

	// Only accept HS256 algorithm
	if hdr.Alg != "HS256" {
		return nil, errors.New("unsupported algorithm")
	}

	// Verify the signature
	signingInput := parts[0] + "." + parts[1]
	if !hmac.Equal([]byte(sign(signingInput)), []byte(parts[2])) {
		return nil, errors.New("bad signature")
	}'''

# Replace the verifyToken function
content = content.replace(old_verify, new_verify)

# Update the comment to reflect the fix
content = content.replace('// flag_5 (A07 authentication_failures): session tokens are JWT-style HS256 tokens,\n// but the verifier trusts the token\'s OWN `alg` header and honours alg:"none"\n// (RFC 7519\'s unsecured JWT) by accepting the payload with NO signature check. A\n// holder of any low-privilege token can re-encode its header as {"alg":"none"},\n// flip role to "admin", drop the signature, and be trusted — a pure base64 forgery\n// requiring only stdlib. The signing secret is high-entropy (brute force is not the\n// path) and disjoint from the flag_3 keystream material.\n// The fix is to reject alg:"none" and require a valid HS256 signature.', 
                      '// SECURITY FIX: JWT verification now properly validates the algorithm header and\n// rejects unsecured tokens (alg:"none"). Only HS256 algorithm is accepted and\n// proper signature verification is enforced.')

# Write the fixed file
with open('/app/jwt.go', 'w') as f:
    f.write(content)

print("JWT vulnerability patched successfully")

