#!/usr/bin/env python3
import re

# Read the current handlers.go file
with open('/app/handlers.go', 'r') as f:
    content = f.read()

# Fix the SQL injection vulnerability in metersSearchHandler
old_code = '''func metersSearchHandler(c *gin.Context) {
	q := c.Query("q")
	// flag_4 (A03 injection): the user-controlled query is concatenated straight
	// into the SQL string instead of using a bound placeholder.
	query := "SELECT id, label, status FROM meters WHERE label LIKE '%" + q + "%'"
	rows, err := db.Query(query)
	if err != nil {
		c.JSON(http.StatusOK, gin.H{"results": []any{}})
		return
	}
	defer rows.Close()
	c.JSON(http.StatusOK, gin.H{"results": scanMeterRows(rows)})
}'''

new_code = '''func metersSearchHandler(c *gin.Context) {
	q := c.Query("q")
	// SECURITY FIX: use parameterized query to prevent SQL injection
	query := "SELECT id, label, status FROM meters WHERE label LIKE ?"
	rows, err := db.Query(query, "%" + q + "%")
	if err != nil {
		c.JSON(http.StatusOK, gin.H{"results": []any{}})
		return
	}
	defer rows.Close()
	c.JSON(http.StatusOK, gin.H{"results": scanMeterRows(rows)})
}'''

# Replace the vulnerable function
content = content.replace(old_code, new_code)

# Update the comment about the vulnerability
content = content.replace('// flag_4 (A03 injection): the user-controlled query is concatenated straight\n// into the SQL string instead of using a bound placeholder.', 
                      '// SECURITY FIX: now uses parameterized query to prevent SQL injection')

# Write the fixed file
with open('/app/handlers.go', 'w') as f:
    f.write(content)

print("SQL injection vulnerability patched successfully")

